def solve(g, rule='mid'):
    out=[r[:] for r in g]; bg=g[0][0]
    for r,row in enumerate(g):
        xs=[c for c,v in enumerate(row) if v!=bg]
        if len(xs)<2: continue
        for a,b in zip(xs,xs[1:]):
            for i in range(a+1,b):
                if row[i]==bg:
                    if rule=='mid': out[r][i]=(bg+sum(set(row)-{bg}))/2
